const express = require('express');
const diagnostics_channel = require('node:diagnostics_channel');
const { AsyncLocalStorage } = require('node:async_hooks');

const app = express();
const tenantStorage = new AsyncLocalStorage();
const queryTraceChannel = diagnostics_channel.channel('db:query:execution');

const traceBuffer = new Map();

queryTraceChannel.subscribe((event) => {
  const context = tenantStorage.getStore() || {};
  traceBuffer.set(event.traceId, {
    tenantId: context.tenantId || 'system',
    sql: event.query,
    params: event.parameters,
    durationMs: event.durationMs,
    timestamp: Date.now()
  });
});

app.use((req, res, next) => {
  const tenantId = req.headers['x-tenant-id'] || 'anonymous';
  tenantStorage.run({ tenantId, user: req.headers['x-user-id'] }, next);
});

app.get('/api/telemetry/traces/:traceId', (req, res) => {
  const currentContext = tenantStorage.getStore();
  const trace = traceBuffer.get(req.params.traceId);

  if (!trace) {
    return res.status(404).json({ error: 'Trace ID not found' });
  }

  // Enforce that the trace belongs to the requesting tenant
  if (trace.tenantId !== currentContext.tenantId) {
    return res.status(403).json({ error: 'Access denied: cannot inspect telemetry from another tenant' });
  }

  res.json({
    traceId: req.params.traceId,
    sql: trace.sql,
    durationMs: trace.durationMs,
    timestamp: trace.timestamp
  });
});

app.listen(9101);
